import json,os
i=json.loads(os.environ['UHM_PROGRAM_INPUTS'])[0]['path']; o=json.loads(os.environ['UHM_PROGRAM_OUTPUTS'])[0]['path']
with open(i,encoding='utf-8') as src, open(o,'w',encoding='utf-8') as dst:
 for line in src:
  obj=json.loads(line)
  if obj.get('keep'): dst.write(json.dumps(obj,sort_keys=True)+'\n')

